def memoize(fn):
    cache = {}
    lock = threading.Lock()

    def wrapper(*args):
        with lock:
            if args not in cache:
                try:
                    cache[args] = (True, fn(*args))
                except Exception as exc:
                    # Do not cache the exception; next call will retry fn.
                    # We leave it uncached so future calls retry.
                    raise
            else:
                success, value = cache[args]
                if success:
                    return value
                else:
                    # This case shouldn't happen since we only store successes,
                    # but handle defensively
                    raise value
        return cache[args][1]

    return wrapper
