import bisect

class RangeSum:
    def __init__(self, nums):
        self.n = len(nums)
        self.nums = list(nums)
        # Segment tree stored in an array of size 4*n
        self.size = 4 * self.n
        self.tree = [0] * self.size
        if self.n > 0:
            self._build(1, 0, self.n - 1)

    def _build(self, node, start, end):
        if start == end:
            self.tree[node] = self.nums[start]
            return
        mid = (start + end) // 2
        left_child = 2 * node
        right_child = 2 * node + 1
        self._build(left_child, start, mid)
        self._build(right_child, mid + 1, end)
        self.tree[node] = self.tree[left_child] + self.tree[right_child]

    def _update(self, node, start, end, idx, value):
        if start == end:
            self.tree[node] = value
            return
        mid = (start + end) // 2
        left_child = 2 * node
        right_child = 2 * node + 1
        if idx <= mid:
            self._update(left_child, start, mid, idx, value)
        else:
            self._update(right_child, mid + 1, end, idx, value)
        self.tree[node] = self.tree[left_child] + self.tree[right_child]

    def _range_sum(self, node, start, end, left, right):
        if right < start or end < left:
            return 0
        if left <= start and end <= right:
            return self.tree[node]
        mid = (start + end) // 2
        left_child = 2 * node
        right_child = 2 * node + 1
        return self._range_sum(left_child, start, mid, left, right) + \
               self._range_sum(right_child, mid + 1, end, left, right)

    def update(self, i, value):
        self.nums[i] = value
        if self.n > 0:
            self._update(1, 0, self.n - 1, i, value)

    def range_sum(self, left, right):
        if self.n == 0 or left > right:
            return 0
        return self._range_sum(1, 0, self.n - 1, left, right)
