def parse_ini(text):
    result = {}
    current_section = "DEFAULT"
    result[current_section] = {}

    current_key = None  # tracks the last key in current section for continuation

    for raw_line in text.splitlines():
        stripped = raw_line.strip()

        # Skip blank lines
        if not stripped:
            continue

        # Skip comments
        if stripped[0] in (';', '#'):
            continue

        # Section header
        if stripped.startswith('[') and stripped.endswith(']'):
            section_name = stripped[1:-1]
            if section_name not in result:
                result[section_name] = {}
            current_section = section_name
            current_key = None
            continue

        # Check for separator (= or :)
        sep_idx = -1
        sep_char = None
        eq_idx = stripped.find('=')
        colon_idx = stripped.find(':')

        if eq_idx != -1 and colon_idx != -1:
            sep_idx = min(eq_idx, colon_idx)
            sep_char = stripped[sep_idx]
        elif eq_idx != -1:
            sep_idx = eq_idx
            sep_char = '='
        elif colon_idx != -1:
            sep_idx = colon_idx
            sep_char = ':'

        if sep_idx != -1:
            key = stripped[:sep_idx].strip().lower()
            value = stripped[sep_idx + 1:].strip()
            result[current_section][key] = value
            current_key = key
        else:
            # No separator: check if it's a continuation line
            # A continuation line is more indented than the key line before it
            # and contains no separator
            if current_key is not None and raw_line != raw_line.lstrip():
                # It's more indented (has leading whitespace)
                # Append to previous value with a single space
                if result[current_section][current_key]:
                    result[current_section][current_key] += ' ' + stripped
                else:
                    result[current_section][current_key] = stripped
            else:
                # Not a valid continuation; ignore or treat as an empty key line
                # According to the rules, this shouldn't happen in valid input
                # But we just ignore it
                pass

    return result
