def retry_with_deadline(fn, retry_on, total_deadline, base_delay, clock, sleep, rand):
    start = clock()
    deadline = start + total_deadline
    n = 0  # retry number, counting first retry as n=1
    while True:
        try:
            return fn()
        except retry_on as e:
            # Compute the delay for the next retry
            delay = base_delay * (2 ** (n)) * rand()
            # Calculate the time when the wait would end
            end_time = clock() + delay
            # If the wait would end at or after the deadline, don't retry
            if end_time >= deadline:
                raise e
            # Sleep for the computed delay
            sleep(delay)
            n += 1
