import math


class RangeSum:
    def __init__(self, nums):
        self.n = len(nums)
        size = 1
        while size < self.n:
            size <<= 1
        self.size = size
        self.tree = [0] * (2 * size)
        for i, val in enumerate(nums):
            self.tree[size + i] = val
        for i in range(size - 1, 0, -1):
            self.tree[i] = self.tree[2 * i] + self.tree[2 * i + 1]

    def update(self, i, value):
        idx = self.size + i
        self.tree[idx] = value
        idx >>= 1
        while idx:
            self.tree[idx] = self.tree[2 * idx] + self.tree[2 * idx + 1]
            idx >>= 1

    def _query(self, l, r):
        # l, r are in tree index space (inclusive)
        res = 0
        l += self.size
        r += self.size
        while l <= r:
            if l & 1:
                res += self.tree[l]
                l += 1
            if not (r & 1):
                res += self.tree[r]
                r -= 1
            l >>= 1
            r >>= 1
        return res

    def range_sum(self, left, right):
        return self._query(left, right)
