def search_last_rotated(nums, target):
    if not nums:
        return -1

    left, right = 0, len(nums) - 1
    last_occurrence = -1

    while left <= right:
        mid = (left + right) // 2

        if nums[mid] == target:
            last_occurrence = mid
            # Try to find a later occurrence
            right = mid - 1
        elif nums[mid] < target:
            left = mid + 1
        else:
            right = mid - 1

    return last_occurrence
