                existing_val = result[current_section].get(last_key, "")
                result[current_section][last_key] = f"{existing_val} {stripped_line}".strip()
            else:
                # Line with no separator and not a continuation is ignored or treated as empty key
                # Based on rules, if it contains no separator and isn't a continuation, 
                # it doesn't match the key-value definition.
                pass

    # Ensure DEFAULT is present if it was used or if the file was empty/only had global keys
    # The rules say keys before any header belong to DEFAULT.
    # If we had keys before any [section], current_section started as "DEFAULT".

    # Final pass to ensure all sections mentioned are in result (already handled above)
    return result
