import copy

def merge(base, overlay):
    # Work on a deep copy to ensure no mutation of base
    result = copy.deepcopy(base)

    if not overlay:
        return result

    # Parse overlay keys into categories for sorting
    # categories: (normalized_name, priority)
    # Priority: ! (0), ~ (1), +prefix (2), +suffix (3), plain (4)
    parsed_overlay = []
    for k, v in overlay.items():
        if k.startswith('!'):
            parsed_overlay.append((k[1:], 0, k, v))
        elif k.startswith('~'):
            parsed_overlay.append((k[1:], 1, k, v))
        elif k.startswith('+'):
            parsed_overlay.append((k[1:], 2, k, v))
        elif k.endswith('+'):
            parsed_overlay.append((k[:-1], 3, k, v))
        else:
            parsed_overlay.append((k, 4, k, v))

    # Sort by normalized name, then by priority
    parsed_overlay.sort(key=lambda x: (x[0], x[1]))

    for _, _, k_raw, v_overlay in parsed_overlay:
        # Remove key
        if k_raw.startswith('!'):
            key = k_raw[1:]
            if key in result:
                del result[key]

        # Set if absent
        elif k_raw.startswith('~'):
            key = k_raw[1:]
            if key not in result:
                result[key] = copy.deepcopy(v_overlay)

        # Prepend
        elif k_raw.startswith('+'):
            key = k_raw[1:]
            if not isinstance(v_overlay, list):
                raise TypeError(f"Value for {k_raw} must be a list")
            curr = result.get(key, [])
            if not isinstance(curr, list):
                raise TypeError(f"Value under {key} must be a list to prepend")
            result[key] = copy.deepcopy(curr) # Ensure we don't mutate base lists
            result[key] = copy.deepcopy(v_overlay) + result[key]

        # Append
        elif k_raw.endswith('+'):
            key = k_raw[:-1]
            if not isinstance(v_overlay, list):
                raise TypeError(f"Value for {k_raw} must be a list")
            curr = result.get(key, [])
            if not isinstance(curr, list):
                raise TypeError(f"Value under {key} must be a list to append")
            result[key] = copy.deepcopy(curr)
            result[key] = result[key] + copy.deepcopy(v_overlay)

        # Plain key
        else:
            key = k_raw
            if key in result:
                v_result = result[key]
                if isinstance(v_result, dict) and isinstance(v_overlay, dict):
                    result[key] = merge(v_result, v_overlay)
                elif not isinstance(v_result, dict) and not isinstance(v_overlay, dict):
                    result[key] = copy.deepcopy(v_overlay)
                else:
                    raise TypeError(f"Type mismatch for key {key}: exactly one value is a dict")
            else:
                result[key] = copy.deepcopy(v_overlay)

    return result
