def parse_ini(text):
    result = {}
    current_section = "DEFAULT"
    last_key = None
    last_indent = 0

    for line in text.splitlines():
        stripped_line = line.strip()

        if not stripped_line or stripped_line.startswith(';') or stripped_line.startswith('#'):
            continue

        # Determine current indentation
        indent = len(line) - len(line.lstrip())

        # Check for section header
        if stripped_line.startswith('[') and stripped_line.endswith(']'):
            current_section = stripped_line[1:-1].strip()
            if current_section not in result:
                result[current_section] = {}
            last_key = None
            continue

        # Check for key-value pair
        # Find the first occurrence of '=' or ':'
        eq_idx = line.find('=')
        col_idx = line.find(':')

        sep_idx = -1
        if eq_idx != -1 and col_idx != -1:
            sep_idx = min(eq_idx, col_idx)
        elif eq_idx != -1:
            sep_idx = eq_idx
        elif col_idx != -1:
            sep_idx = col_idx

        if sep_idx != -1:
            # This is a new key-value pair
            key = line[:sep_idx].strip().lower()
            value = line[sep_idx + 1:].strip()

            if current_section not in result:
                result[current_section] = {}

            result[current_section][key] = value
            last_key = key
            last_indent = indent
        else:
            # No separator: check if it is a continuation
            if last_key is not None and indent > last_indent:
                if current_section in result and last_key in result[current_section]:
                    result[current_section][last_key] += " " + stripped_line
            else:
                # Invalid line or key without value (not defined by rules, effectively ignored)
                last_key = None

    # Ensure DEFAULT exists if keys appeared before any section
    # (Handled by the `if current_section not in result` logic above)

    return result
