import copy


def _parse_key(key):
    """Parse a key and determine sigil type and base name.

    Returns (sigil, base_name, order_index) where:
    - sigil is one of: None, '!', '~', '+_prepend', '+_append'
    - base_name is the key with sigil removed
    - order_index: 0=remove, 1=set-if-absent, 2=prepend, 3=append, 4=plain
    """
    # Check for leading sigils
    if key.startswith('!') and len(key) > 1:
        return ('!', key[1:], 0)
    if key.startswith('~') and len(key) > 1:
        return ('~', key[1:], 1)
    if key.startswith('+') and len(key) > 1:
        return ('+_prepend', key[1:], 2)
    # Check for trailing sigil
    if key.endswith('+') and len(key) > 1:
        return ('+_append', key[:-1], 3)
    # Plain key
    return (None, key, 4)


def merge(base, overlay):
    """Merge a configuration dict base with an overlay dict.

    Returns a new dict. Neither base nor overlay is mutated.
    """
    result = copy.deepcopy(base)

    if not overlay:
        return result

    # Parse all keys to determine their sigils and base names
    parsed = []
    for key in overlay:
        sigil, base_name, order = _parse_key(key)
        parsed.append((key, sigil, base_name, order))

    # Group by base_name, keeping track of order
    from collections import OrderedDict
    groups = OrderedDict()
    for key, sigil, base_name, order in parsed:
        if base_name not in groups:
            groups[base_name] = []
        groups[base_name].append((key, sigil, base_name, order))

    # Sort base names
    sorted_base_names = sorted(groups.keys())

    for base_name in sorted_base_names:
        entries = groups[base_name]
        # Sort by order index (remove, set-if-absent, prepend, append, plain)
        entries.sort(key=lambda x: x[3])

        for key, sigil, name, order in entries:
            value = overlay[key]

            if sigil == '!':
                # Remove key from result
                if name in result:
                    del result[name]

            elif sigil == '~':
                # Set if absent
                if name not in result:
                    result[name] = copy.deepcopy(value)
                # If name is in result, do nothing

            elif sigil == '+_prepend':
                # Prepend list
                if not isinstance(value, list):
                    raise TypeError(f"Value for '+{name}' must be a list, got {type(value).__name__}")
                if name in result:
                    if not isinstance(result[name], list):
                        raise TypeError(f"Value for '{name}' in result must be a list for '+{name}', got {type(result[name]).__name__}")
                    result[name] = value + result[name]
                else:
                    result[name] = copy.deepcopy(value)

            elif sigil == '+_append':
                # Append list
                if not isinstance(value, list):
                    raise TypeError(f"Value for '{name}+' must be a list, got {type(value).__name__}")
                if name in result:
                    if not isinstance(result[name], list):
                        raise TypeError(f"Value for '{name}' in result must be a list for '{name}+', got {type(result[name]).__name__}")
                    result[name] = result[name] + value
                else:
                    result[name] = copy.deepcopy(value)

            else:
                # Plain key
                if name in result:
                    result_val = result[name]
                    if isinstance(result_val, dict) and isinstance(value, dict):
                        # Recursive merge
                        result[name] = merge(result_val, value)
                    elif isinstance(result_val, dict) != isinstance(value, dict):
                        # Exactly one is a dict -> TypeError
                        raise TypeError(f"Cannot merge dict with non-dict for key '{name}'")
                    else:
                        # Otherwise, replace
                        result[name] = copy.deepcopy(value)
                else:
                    # Key not in result, set it
                    result[name] = copy.deepcopy(value)

    return result
