    lo, hi = 0, n - 1
    pivot = 0
    while lo <= hi:
        mid = (lo + hi) // 2
        if nums[mid] > nums[hi]:
            lo = mid + 1
        elif nums[mid] < nums[hi]:
            hi = mid - 1
        else:
            hi -= 1

    pivot = lo  # lo now points to the smallest element

    # Determine which part of the array to search
    if nums[pivot] <= target <= nums[n - 1]:
        return find_last(nums, pivot, n - 1, target)
    else:
        return find_last(nums, 0, pivot - 1, target)
