def search_last_rotated(nums, target):
    n = len(nums)
    if n == 0:
        return -1

    def find_pivot(arr):
        lo, hi = 0, len(arr) - 1
        if lo == hi:
            return lo
        if arr[lo] < arr[hi]:
            return lo
        if arr[lo] > arr[hi]:
            # Binary search for pivot (smallest element)
            lo, hi = 0, len(arr) - 1
            while lo < hi:
                mid = (lo + hi) // 2
                if arr[mid] > arr[hi]:
                    lo = mid + 1
                else:
                    hi = mid
            return lo
        # arr[lo] == arr[hi], need linear scan or careful handling
        # Use linear scan from the left to find the minimum
        min_val = arr[0]
        min_idx = 0
        for i in range(1, len(arr)):
            if arr[i] < min_val:
                min_val = arr[i]
                min_idx = i
        return min_idx

    pivot = find_pivot(nums)

    # Now the array is composed of two sorted parts: nums[pivot:] and nums[:pivot]
    # We need to find the last occurrence of target.
    # We can do binary search in both parts and take the later index.

    def search_last_in_sorted(arr, start, end, target):
        """Find last occurrence of target in arr[start..end] (inclusive), which is sorted."""
        lo, hi = start, end
        result = -1
        while lo <= hi:
            mid = (lo + hi) // 2
            if arr[mid] == target:
                result = mid
                lo = mid + 1
            elif arr[mid] < target:
                lo = mid + 1
            else:
                hi = mid - 1
        return result

    # Part 1: nums[pivot : n]
    # Part 2: nums[0 : pivot]
    candidate1 = -1
    candidate2 = -1

    if pivot < n:
        candidate1 = search_last_in_sorted(nums, pivot, n - 1, target)
    if pivot > 0:
        candidate2 = search_last_in_sorted(nums, 0, pivot - 1, target)

    # Return the maximum index among valid candidates
    result = max(candidate1, candidate2)
    return result if result != -1 else -1
