import copy
from typing import Any


def _classify_key(key: str):
    """Classify a key by its sigils.

    Returns (sigil, base_name) where sigil is one of:
    - 'remove' for !key
    - 'set_if_absent' for ~key
    - 'prepend' for +key
    - 'append' for key+
    - 'plain' for plain keys
    """
    if key.startswith('!') and len(key) > 1:
        return 'remove', key[1:]
    if key.startswith('~') and len(key) > 1:
        return 'set_if_absent', key[1:]
    if key.startswith('+') and len(key) > 1:
        return 'prepend', key[1:]
    if key.endswith('+') and len(key) > 1:
        return 'append', key[:-1]
    return 'plain', key


def _sigil_order(sigil: str) -> int:
    """Return the ordering priority for sigils with the same base name.

    Order: remove, set-if-absent, prepend, append, plain set
    """
    order = {
        'remove': 0,
        'set_if_absent': 1,
        'prepend': 2,
        'append': 3,
        'plain': 4,
    }
    return order.get(sigil, 4)


def merge(base: dict, overlay: dict) -> dict:
    """Merge a configuration dict `base` with an overlay dict `overlay`.

    Returns a new dict combining base and overlay without mutating either.
    """
    result = copy.deepcopy(base)

    if not overlay:
        return result

    # Classify all overlay keys and sort them by (base_name, sigil_order)
    classified = []
    for key in overlay:
        sigil, base_name = _classify_key(key)
        classified.append((base_name, _sigil_order(sigil), sigil, key))

    # Sort by base name first, then by sigil order
    classified.sort(key=lambda x: (x[0], x[1]))

    for base_name, _, sigil, original_key in classified:
        value = overlay[original_key]

        if sigil == 'remove':
            # Remove key from result; no-op if not present
            result.pop(base_name, None)

        elif sigil == 'set_if_absent':
            # Set key to value only if not already in result
            if base_name not in result:
                result[base_name] = copy.deepcopy(value)

        elif sigil == 'prepend':
            # Prepend value (must be list) to list under base_name
            if not isinstance(value, list):
                raise TypeError(f"Value for '+{base_name}' must be a list")
            if base_name in result:
                if not isinstance(result[base_name], list):
                    raise TypeError(f"Value at '{base_name}' must be a list for prepend")
                result[base_name] = list(value) + result[base_name]
            else:
                result[base_name] = copy.deepcopy(value)

        elif sigil == 'append':
            # Append value (must be list) to list under base_name
            if not isinstance(value, list):
                raise TypeError(f"Value for '{base_name}+' must be a list")
            if base_name in result:
                if not isinstance(result[base_name], list):
                    raise TypeError(f"Value at '{base_name}' must be a list for append")
                result[base_name] = result[base_name] + list(value)
            else:
                result[base_name] = copy.deepcopy(value)

        elif sigil == 'plain':
            # Plain key: merge or replace
            if base_name in result:
                both_dicts = isinstance(result[base_name], dict) and isinstance(value, dict)
                one_dict_only = (isinstance(result[base_name], dict) != isinstance(value, dict))

                if both_dicts:
                    # Recursive merge
                    result[base_name] = merge(result[base_name], value)
                elif one_dict_only:
                    raise TypeError(f"Cannot merge dict with non-dict for key '{base_name}'")
                else:
                    # Replace
                    result[base_name] = copy.deepcopy(value)
            else:
                # Key not in result, just set it
                result[base_name] = copy.deepcopy(value)

    return result
