def run(program, max_steps):
    MOD = 2**64
    regs = [0, 0, 0, 0]
    flag = 0
    pc = 0
    steps = 0
    n = len(program)

    def resolve(val):
        if isinstance(val, str):
            if val.startswith('r'):
                return regs[int(val[1:])]
            else:
                return int(val[1:]) % MOD
        return val % MOD  # this shouldn't happen for normal operands

    while True:
        # Check PC bounds before fetch
        if pc < 0 or pc >= n:
            return {"regs": regs, "flag": flag, "pc": pc, "steps": steps, "reason": "fell_off"}
        # Check step limit before fetch
        if steps == max_steps:
            return {"regs": regs, "flag": flag, "pc": pc, "steps": steps, "reason": "step_limit"}

        instr = program[pc]
        opcode = instr[0]

        if opcode == "SET":
            dst = instr[1]
            src = instr[2]
            if isinstance(dst, str) and dst.startswith('r'):
                di = int(dst[1:])
                src_val = resolve(src)
                regs[di] = src_val % MOD
            pc += 1

        elif opcode == "ADD":
            dst = instr[1]
            src = instr[2]
            if isinstance(dst, str) and dst.startswith('r'):
                di = int(dst[1:])
                src_val = resolve(src)
                regs[di] = (regs[di] + src_val) % MOD
            pc += 1

        elif opcode == "SUB":
            dst = instr[1]
            src = instr[2]
            if isinstance(dst, str) and dst.startswith('r'):
                di = int(dst[1:])
                src_val = resolve(src)
                regs[di] = (regs[di] - src_val) % MOD
            pc += 1

        elif opcode == "MUL":
            dst = instr[1]
            src = instr[2]
            if isinstance(dst, str) and dst.startswith('r'):
                di = int(dst[1:])
                src_val = resolve(src)
                regs[di] = (regs[di] * src_val) % MOD
            pc += 1

        elif opcode == "CMP":
            a = instr[1]
            b = instr[2]
            a_val = resolve(a)
            b_val = resolve(b)
            flag = 1 if a_val < b_val else 0
            pc += 1

        elif opcode == "JMP":
            off = instr[1]
            target = pc + off
            if target < 0 or target >= n:
                return {"regs": regs, "flag": flag, "pc": pc, "steps": steps, "reason": "bad_jump"}
            pc = target

        elif opcode == "JIF":
            off = instr[1]
            if flag == 1:
                target = pc + off
                if target < 0 or target >= n:
                    return {"regs": regs, "flag": flag, "pc": pc, "steps": steps, "reason": "bad_jump"}
                pc = target
            else:
                pc += 1

        elif opcode == "ROT":
            # (r0, r1, r2, r3) -> (r1, r2, r3, r0)
            regs = [regs[1], regs[2], regs[3], regs[0]]
            pc += 1

        elif opcode == "HALT":
            return {"regs": regs, "flag": flag, "pc": pc, "steps": steps, "reason": "halt"}

        # Count this step
