import copy


def merge(base, overlay):
    """Merge base with overlay, returning a new dict without mutating either argument."""
    # Deep copy base
    result = copy.deepcopy(base)

    # Apply overlay
    _apply_overlay(result, overlay)

    return result


def _apply_overlay(result, overlay):
    """Apply overlay rules to result in place. overlay is not mutated."""
    if not overlay:
        return

    # Collect keys with their parsed sigils
    # Each key in overlay is processed; we need to determine sigil type and base name
    entries = []  # list of (sort_key, sigil_type, name, value)

    for key in overlay:
        sigil, name = _parse_key(key)
        value = overlay[key]
        entries.append((sigil, name, value, key))

    # Sort by (name, sigil_priority)
    # sigil_priority order: remove(!), set-if-absent(~), prepend(+ at start), append(+ at end), plain set
    # We need a priority number for sorting
    def sigil_priority(sigil):
        if sigil == 'remove':
            return 0
        elif sigil == 'set_if_absent':
            return 1
        elif sigil == 'prepend':
            return 2
        elif sigil == 'append':
            return 3
        else:  # plain
            return 4

    entries.sort(key=lambda e: (e[1], sigil_priority(e[0])))

    for sigil, name, value, original_key in entries:
        _apply_single(result, sigil, name, value)


def _parse_key(key):
    """Parse a key to determine its sigil and base name.

    Returns (sigil, name) where sigil is one of:
    'remove' (!key), 'set_if_absent' (~key), 'prepend' (+key), 'append' (key+), or 'plain'.
    """
    if key.startswith('!'):
        return ('remove', key[1:])
    elif key.startswith('~'):
        return ('set_if_absent', key[1:])
    elif key.startswith('+') and len(key) > 1:
        return ('prepend', key[1:])
    elif key.endswith('+') and len(key) > 1:
        return ('append', key[:-1])
    else:
        return ('plain', key)


def _apply_single(result, sigil, name, value):
    """Apply a single overlay operation to result."""
    if sigil == 'remove':
        if name in result:
            del result[name]
        # No-op if not present

    elif sigil == 'set_if_absent':
        if name not in result:
            result[name] = copy.deepcopy(value)
        # No-op if present

    elif sigil == 'prepend':
        if not isinstance(value, list):
            raise TypeError(f"Value for prepend key must be a list, got {type(value).__name__}")
        if name in result:
            if not isinstance(result[name], list):
                raise TypeError(f"Key '{name}' in result is not a list, cannot prepend")
            # Prepend: value goes before existing
            new_list = copy.deepcopy(value) + result[name]
            result[name] = new_list
        else:
            result[name] = copy.deepcopy(value)

    elif sigil == 'append':
        if not isinstance(value, list):
            raise TypeError(f"Value for append key must be a list, got {type(value).__name__}")
        if name in result:
            if not isinstance(result[name], list):
                raise TypeError(f"Key '{name}' in result is not a list, cannot append")
            # Append: value goes after existing
            new_list = result[name] + copy.deepcopy(value)
            result[name] = new_list
        else:
            result[name] = copy.deepcopy(value)

    elif sigil == 'plain':
        if name in result:
            existing = result[name]
            # If both are dicts, merge recursively
            if isinstance(existing, dict) and isinstance(value, dict):
                _apply_overlay(existing, value)
            elif isinstance(existing, dict) or isinstance(value, dict):
                # Exactly one is a dict
                raise TypeError(f"Cannot merge dict with non-dict for key '{name}'")
            else:
                # Neither is a dict, or both are non-dict (including lists, scalars, None)
                result[name] = copy.deepcopy(value)
        else:
            result[name] = copy.deepcopy(value)
