            return regs[idx]
        elif isinstance(op, str) and op.startswith("#"):
            return int(op[1:]) % MOD
        else:
            # Should not happen for register/immediate operands
            raise ValueError(f"Invalid operand: {op}")

    def set_reg(dst, val):
        idx = {"r0": 0, "r1": 1, "r2": 2, "r3": 3}[dst]
        regs[idx] = val % MOD

    while True:
        # Before fetching each instruction:
        # Check if pc is out of range
