def search_last_rotated(nums, target):
    """
    Find the index of the last occurrence of target in a rotated sorted array
    that may contain duplicates.
    """
    if not nums:
        return -1

    n = len(nums)

    # Binary search to find the last occurrence
    left, right = 0, n - 1
    result = -1

    while left <= right:
        mid = (left + right) // 2

        if nums[mid] == target:
            result = mid
            # Move right to find the last occurrence
            left = mid + 1
        elif nums[mid] < target:
            # Target could be in the right half
            # But we need to handle rotation and duplicates
            if nums[left] == nums[mid] == target:
                # All three are equal, check left part
                if nums[left] == target:
                    # Could be in left part, but we're looking for last, so check right first
                    right = mid - 1
                else:
                    left = mid + 1
            elif nums[left] <= nums[mid]:
                # Left half is sorted
                if nums[left] <= target < nums[mid]:
                    right = mid - 1
                else:
                    left = mid + 1
            else:
                # Right half is sorted
                if nums[mid] < target <= nums[right]:
                    left = mid + 1
                else:
                    right = mid - 1
        else:
            # nums[mid] > target
            if nums[left] == nums[mid] == target:
                # This case shouldn't happen since nums[mid] > target
                pass
            if nums[left] == nums[mid]:
                # Duplicates, check left
                if nums[left] == target:
                    left = mid + 1
                else:
                    right = mid - 1
            elif nums[left] <= nums[mid]:
                # Left half is sorted
                if nums[left] <= target < nums[mid]:
                    right = mid - 1
                else:
                    left = mid + 1
            else:
                # Right half is sorted
                if nums[mid] < target <= nums[right]:
                    left = mid + 1
                else:
                    right = mid - 1

    return result
