def _apply_overlay(result, overlay):
    """Apply overlay dict to result dict in-place (result must already be a copy)."""
    # Collect all entries and sort them by (sigil-removed name, priority)
    # Priority: remove(0), set-if-absent(1), prepend(2), append(3), plain(4)

    entries = []
    for key, value in overlay.items():
        name, sigil_type, priority = _parse_key(key)
        entries.append((name, priority, key, value))

    # Sort by name first, then by priority
    entries.sort(key=lambda x: (x[0], x[1]))

    for name, priority, original_key, value in entries:
        _apply_single(result, name, priority, value)


def _parse_key(key):
    """
    Parse a key to determine its sigil type and priority.
    Returns (name, sigil_type, priority) where:
      sigil_type: 'remove', 'set_if_absent', 'prepend', 'append', 'plain'
      priority: 0=remove, 1=set_if_absent, 2=prepend, 3=append, 4=plain

    Rules:
      - '!' as first char: remove
      - '~' as first char: set-if-absent
      - '+' as first char: prepend
      - '+' as last char (and not first): append
      - Otherwise: plain
    """
    if key.startswith('!'):
        return key[1:], 'remove', 0
    if key.startswith('~'):
        return key[1:], 'set_if_absent', 1
    if key.startswith('+'):
        # Check if it's also the only character or just prepend
        # "+key" means prepend
        return key[1:], 'prepend', 2
    if key.endswith('+') and len(key) > 1:
        # "key+" means append
        return key[:-1], 'append', 3
    # Plain key
    return key, 'plain', 4


def _apply_single(result, name, sigil_type, value):
    """Apply a single overlay entry to the result dict."""
    if sigil_type == 'remove':
        if name in result:
            del result[name]
        # no-op if not present

    elif sigil_type == 'set_if_absent':
        if name not in result:
            result[name] = copy.deepcopy(value)
        # do nothing otherwise

    elif sigil_type == 'prepend':
        _merge_list(result, name, value, prepend=True)

    elif sigil_type == 'append':
        _merge_list(result, name, value, prepend=False)

    elif sigil_type == 'plain':
        _plain_merge(result, name, value)


def _merge_list(result, name, value, prepend):
    """Handle +key and key+ operations."""
    if not isinstance(value, list):
        raise TypeError(f"Overlay value for '{name}+' or '+{name}' must be a list")

    if name in result:
        existing = result[name]
        if not isinstance(existing, list):
            raise TypeError(f"Key '{name}' in result holds a non-list value; cannot prepend/append")
        # Create a new list without mutating existing
        if prepend:
            result[name] = copy.deepcopy(value) + copy.deepcopy(existing)
        else:
            result[name] = copy.deepcopy(existing) + copy.deepcopy(value)
    else:
        # Key not in result; treat as empty list
        result[name] = copy.deepcopy(value)


def _plain_merge(result, name, value):
    """Handle plain key merging."""
    if name in result:
        existing = result[name]
        if isinstance(existing, dict) and isinstance(value, dict):
            # Recursive merge
            new_dict = copy.deepcopy(existing)
            _apply_overlay(new_dict, value)
            result[name] = new_dict
        elif isinstance(existing, dict) != isinstance(value, dict):
            # Exactly one is a dict
            raise TypeError(f"Cannot merge dict with non-dict value for key '{name}'")
        else:
            # Both non-dict, or both lists, or both primitives: overlay replaces
            result[name] = copy.deepcopy(value)
    else:
        # Key not in result
        result[name] = copy.deepcopy(value)
